# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# calculate_residuals ----
## Setup ----
# A small estimates tibble with one stream of each distribution
residual_estimates <- tibble::tibble(
  module_id = c(1L, 1L, 2L, 2L, 3L, 3L, 3L, 3L, 3L, 3L),
  label = c(
    rep("index_expected", 2), rep("catch_expected", 2),
    rep("agecomp_expected", 6)
  ),
  year_i = c(1L, 2L, 1L, 2L, 1L, 1L, 1L, 2L, 2L, 2L),
  age = c(NA, NA, NA, NA, 1, 2, 3, 1, 2, 3),
  expected = c(10, 12, log(100), log(200), 0.2, 0.3, 0.5, 0.1, 0.4, 0.5),
  observed = c(11, 10, 120, 180, 30, 20, 50, 5, 45, 50),
  distribution = c(
    rep("normal", 2), rep("log_normal", 2), rep("multinomial", 6)
  ),
  input_type = "data",
  log_sd = c(log(2), log(2), log(0.1), log(0.1), rep(NA, 6))
)

## IO correctness ----
test_that("`calculate_residuals()` works with correct inputs", {
  residuals <- calculate_residuals(residual_estimates)[["resids"]]

  #' @description Test that `calculate_residuals()` adds a `resids` column right after `observed`.
  expect_equal(
    object = which(names(calculate_residuals(residual_estimates)) == "resids"),
    expected = which(names(residual_estimates) == "observed") + 1
  )

  #' @description Test that `calculate_residuals()` returns (y - mu) / sd for normal data.
  expect_equal(object = residuals[1:2], expected = c(11 - 10, 10 - 12) / 2)

  #' @description Test that `calculate_residuals()` returns response-scale Pearson residuals for log-normal data.
  sdlog <- 0.1
  meanlog <- log(c(100, 200))
  lognormal_mean <- exp(meanlog + sdlog^2 / 2)
  lognormal_variance <- exp(2 * meanlog + sdlog^2) * (exp(sdlog^2) - 1)
  expect_equal(
    object = residuals[3:4],
    expected = (c(120, 180) - lognormal_mean) / sqrt(lognormal_variance)
  )

  #' @description Test that `calculate_residuals()` uses the composition total as the multinomial sample size.
  observed <- c(30, 20, 50, 5, 45, 50)
  proportion <- c(0.2, 0.3, 0.5, 0.1, 0.4, 0.5)
  size <- rep(c(100, 100), each = 3)
  expect_equal(
    object = residuals[5:10],
    expected = (observed - size * proportion) /
      sqrt(size * proportion * (1 - proportion))
  )
})

test_that("`calculate_residuals()` works with get_estimates() output", {
  estimates <- get_estimates(FIMS::fit_big_optimized)
  #' @description Test that `get_estimates()` returns a `resids` column.
  expect_true("resids" %in% names(estimates))
  #' @description Test that `get_estimates()` only returns residuals for data rows.
  expect_true(all(is.na(estimates[["resids"]][
    !estimates[["input_type"]] %in% "data"
  ])))
  #' @description Test that `get_estimates()` returns finite residuals for every data stream in the example model.
  data_rows <- dplyr::filter(estimates, .data$input_type %in% "data")
  expect_true(all(
    tapply(is.finite(data_rows[["resids"]]), data_rows[["label"]], any)
  ))
  #' @description Test that `calculate_residuals()` gives the same answer when run twice.
  expect_identical(object = calculate_residuals(estimates), expected = estimates)
})

## Edge handling ----
test_that("`calculate_residuals()` returns correct outputs for edge cases", {
  edge_estimates <- residual_estimates
  # A missing bin in the second age composition
  edge_estimates[["observed"]][9] <- -999
  # An expected proportion of zero in the first age composition
  edge_estimates[["expected"]][5:7] <- c(0, 0.5, 0.5)
  # A row that is not data
  edge_estimates[["input_type"]][1] <- "random_effects"
  residuals <- calculate_residuals(edge_estimates)[["resids"]]

  #' @description Test that `calculate_residuals()` returns NA for rows that are not data.
  expect_true(is.na(residuals[1]))
  #' @description Test that `calculate_residuals()` returns NA for a bin with an expected proportion of zero.
  expect_true(is.na(residuals[5]))
  #' @description Test that `calculate_residuals()` returns NA for every bin of a composition with a missing bin.
  expect_true(all(is.na(residuals[8:10])))
  #' @description Test that `calculate_residuals()` returns NA for a distribution without residuals.
  other_estimates <- residual_estimates
  other_estimates[["distribution"]][1] <- "other"
  expect_true(is.na(calculate_residuals(other_estimates)[["resids"]][1]))
  #' @description Test that `calculate_residuals()` replaces an existing `resids` column.
  twice <- calculate_residuals(calculate_residuals(residual_estimates))
  expect_equal(object = sum(names(twice) == "resids"), expected = 1)
})

## Error handling ----
test_that("`calculate_residuals()` returns correct error messages", {
  #' @description Test that `calculate_residuals()` errors for a type that is not available.
  expect_error(
    object = calculate_residuals(residual_estimates, type = "deviance")
  )
  #' @description Test that `calculate_residuals()` errors when a required column is missing.
  expect_error(
    object = calculate_residuals(
      dplyr::select(residual_estimates, -"expected")
    ),
    regexp = "missing"
  )
})
